// tests/content-assets.test.mjs — the public website's content assets added on 2026-10-22:
//
//   /llms.txt                                                  what an AI assistant should know about the business (the llms.txt convention)
//   /guides/                                                   index
//   /guides/commissary-kitchen-requirements-philippines/       article
//   /guides/ss304-vs-ss316-stainless-steel/                    article
//   /downloads/barro-industries-company-profile.pdf            three downloadable documents, generated by scripts/build-downloads.js
//   /downloads/barro-industries-catalogue.pdf
//   /downloads/barro-industries-portfolio.pdf
//
// What is pinned:
//   · llms.txt: the convention (an H1, a blockquote summary, H2 sections of links), every link resolves to a file or to a PLANNED page, only the facts the owner
//     confirmed, no amount, no banned name, no draft page listed while it is a draft;
//   · each guide: the head (title, description, canonical, Open Graph, Twitter, CSP, stylesheets), one H1, a logical heading order, unique ids, sized and described
//     images, Article / BreadcrumbList / FAQPage JSON-LD that says what the page says (the FAQ word for word), the draft marker <=> noindex, the site's header and
//     footer, the owner's content rules (no price or peso amount, no partner company, Quezon City contact only, no project count, no client but DMMMSU / ISPSC, no
//     superlative, no specific legal citation in the commissary guide, British spelling), 900-1600 words, working internal links;
//   · each PDF: it exists and is under the size cap, A4, the page count, every page numbered and carrying the website address, and its TEXT (read back out of the
//     PDF by scripts/downloads/pdf-text.js) passes the banned-content scan, carries the Quezon City address, the phone number and hello@, never names the restaurant that
//     is shown anonymously, and (catalogue) shows every product note and specification of the website's catalogue in full;
//   · copyright (owner approved 2026-10-22): the guides carry author / copyright meta, copyrightHolder in their JSON-LD and a visible notice; each PDF carries a
//     "© 2026 Barro Industries OPC · barroindustries.com" footer on every page, a back-page sentence (ours, not to be copied or reused without written
//     permission), Author / Creator / Producer = Barro Industries OPC, a Subject naming Barro Kitchens, Keywords, a Copyright line and an XMP packet; the
//     pictures that only the PDFs use are marked and carry XMP;
//   · the build: the script, the shared stylesheet, the embedded font and its licence, the HTML sources (noindex), and the way to regenerate.
//
// Run with: node --test tests/*.test.mjs
// Failing after a change to catalogue/index.html? The catalogue PDF is built from it: run  node scripts/build-downloads.js catalogue

import { describe, it } from 'node:test';
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { createRequire } from 'node:module';
import { fileURLToPath } from 'node:url';

const ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');
const require = createRequire(import.meta.url);
const { pdfPages, pdfInfo, compact } = require(path.join(ROOT, 'scripts/downloads/pdf-text.js'));
const { readMeta } = require(path.join(ROOT, 'scripts/downloads/pdf-meta.js'));
const read = (rel) => fs.readFileSync(path.join(ROOT, rel), 'utf8');
const exists = (rel) => fs.existsSync(path.join(ROOT, rel));
const BASE = 'https://barroindustries.com';

