const PHONE = '0927 683 6300';
const EMAIL = 'hello@barroindustries.com';
const MSGR = 'https://m.me/barrokitchens';
const FB = 'https://www.facebook.com/barrokitchens';
const PLACES = ['Ilocos Sur', 'La Union', 'Baguio', 'La Trinidad', 'Tarlac', 'Pampanga', 'Bulacan', 'Iba', 'Subic', 'Manila', 'Cavite', 'Laguna', 'Batangas'];
// pages another agent is building now (2026-10-22): they may not exist yet, but links to them are intended
const PLANNED = new Set(['/products/', '/products/stainless-steel-sinks/', '/products/stainless-steel-work-tables/', '/products/commercial-gas-stoves/', '/products/stainless-steel-cabinets/', '/products/stainless-steel-shelving/', '/products/stainless-steel-racks/', '/services/fresh-air-systems/']);

// ── what the public site never says (the same rulings as CHECK 9 and tests/seo-pages.test.mjs) ──────────────────────────────────────────
const RE = {
  money: /₱|\bPHP ?\d|\bpesos?\b|\b\d{1,3}(,\d{3})+\b/i,
  priceWords: /\bpric(e|es|ed|ing)\b|\bcost(s|ing)?\b|\bcheap(er|est)?\b|\baffordabl\w*|\bdiscounts?\b|\bpromos?\b|\bfree\b|\boffers?\b|\boffered\b|\bbudget\b|\bbargain|\bmarkup\b/i,
  brands: /brilliant[\s\-_.]*steel|barro[\s\-_.]*steel|\bvesta\b/i,
  contact: /gmail|0960|san\s*fernando|purok|carlatan/i,
  superlative: /\b(best|leading|world[- ]class|award(?:s|[- ]winning)?|certified|certification|accredit\w*|licen[cs]\w*|guarantee[ds]?|unrivall?ed|unmatched|unbeatable|number one|top[- ]rated|premier|foremost|finest|safest|flawless|perfect|government[- ]approved|official(?:ly)?|endorse\w*)\b|#1/i,
  system: /operat(?:ing|ions?)\s+system|central\s+system|ops\s+system|\bBI Ops\b|\bapp shell\b|firebase|\bPWA\b|\bsign[- ]?in\b|\blog[- ]?in\b/i,
  counts: /(?<![\w])(?!0\d\b)\d[\d,]*\+?\s+(projects|clients|customers|kitchens installed|installations|installed kitchens)\b|\b(hundreds|dozens|numerous|countless)\s+of\b|\b500\+|\bover \d+ (projects|clients)\b/i,
  us: /\b(catalog(?!ue)|colors?|centers?|meters?|labor|fiber(?:glass)?|galvaniz\w*|steriliz\w*|organiz\w*|customiz\w*|optimiz\w*|specializ\w*|standardiz\w*|centraliz\w*|minimiz\w*|maximiz\w*|utiliz\w*|recogniz\w*|summariz\w*|gray|aluminum|analyze[ds]?|defense|favor\w*|neighbor\w*|program(?!me))\b/i,
  // a specific legal instrument, permit name or code clause: the commissary guide must send the reader to the offices instead
  legal: /\b(Republic Act|R\.?A\.? ?\d{3,}|Presidential Decree|P\.?D\.? ?\d{3,}|(?:National )?Building Code|Fire Code|Sanitation Code|NFPA|ASTM|ISO ?\d{3,}|FSIC|FSEC|HACCP|Section \d+|Article \d+|clause \d+)\b/i,
};
const ALLOWED_INSTITUTIONS = new Set(['Don Mariano Marcos Memorial State University', 'Ilocos Sur Polytechnic State College']);
// every "<Capitalised words> University / College / Hospital / Hotel ..." phrase in a text must END with one of the two allowed names (a PDF prints a label such as CLIENT before it)
function assertInstitutions(text, label) {
  // the footer's own download label "Company profile (PDF)" is our document, not another company
  for (const m of text.replace(/\bCompany profile \(PDF\)/g, '').matchAll(/\b((?:[A-Z][A-Za-z.'’&-]*\s+){0,7}(?:University|College|Institute|Hospital|Corporation|Company|Academy|Foundation|Hotel|Mall|Bank))\b/g)) assert.ok([...ALLOWED_INSTITUTIONS].some((a) => m[1].endsWith(a)), `${label}: another institution is named: ${m[1]}`);
}
// the values of a JSON-LD graph, without the schema.org vocabulary ("@type": "Organization" is not English prose)
const ldValues = (v, out = []) => { if (typeof v === 'string') out.push(v); else if (Array.isArray(v)) v.forEach((x) => ldValues(x, out)); else if (v && typeof v === 'object') for (const [k, x] of Object.entries(v)) if (!k.startsWith('@')) ldValues(x, out); return out; };

// ── a small HTML scanner (no dependency; the same idea as tests/seo-pages.test.mjs) ─────────────────────────────────────────────────────
const VOID = new Set(['area', 'base', 'br', 'col', 'embed', 'hr', 'img', 'input', 'link', 'meta', 'param', 'source', 'track', 'wbr']);
function parseAttrs(s) {
  const out = {};
  const re = /([^\s=\/"'>]+)(?:\s*=\s*(?:"([^"]*)"|'([^']*)'|([^\s"'>]+)))?/g;
  let m;
  while ((m = re.exec(s))) out[m[1].toLowerCase()] = m[2] !== undefined ? m[2] : m[3] !== undefined ? m[3] : m[4] !== undefined ? m[4] : '';
  return out;
}
function scan(html) {
  const out = { texts: [], attrs: [], comments: [], scripts: [], elements: [], problems: [] };
  const stack = [];
  const lower = html.toLowerCase();
  const re = /<!--([\s\S]*?)-->|<!doctype[^>]*>|<(\/?)([a-zA-Z][a-zA-Z0-9:-]*)((?:"[^"]*"|'[^']*'|[^'">])*)>/gi;
  let last = 0, m;
  const addText = (t) => { if (t.trim()) out.texts.push({ text: t, chain: stack.slice() }); };
  while ((m = re.exec(html))) {
    addText(html.slice(last, m.index));
    last = re.lastIndex;
    if (m[1] !== undefined) { out.comments.push({ text: m[1], chain: stack.slice() }); continue; }
    if (m[3] === undefined) continue;
    const closing = m[2] === '/', tag = m[3].toLowerCase(), rawAttrs = m[4];
    if (closing) {
      let i = stack.length - 1;
      while (i >= 0 && stack[i].tag !== tag) i--;
      if (i < 0) { out.problems.push(`stray </${tag}> at ${m.index}`); continue; }
      if (i !== stack.length - 1) out.problems.push(`</${tag}> closes over unclosed <${stack.slice(i + 1).map((e) => e.tag).join('>, <')}> at ${m.index}`);
      stack.length = i;
      continue;
    }
    const attrs = parseAttrs(rawAttrs);
    const el = { tag, attrs };
    out.elements.push({ tag, attrs, chain: stack.slice() });
    for (const [k, v] of Object.entries(attrs)) out.attrs.push({ name: k, value: v, tag, chain: stack.slice() });
    if (tag === 'script' || tag === 'style') {
      const close = lower.indexOf('</' + tag, re.lastIndex);
      if (tag === 'script') out.scripts.push({ attrs, body: html.slice(re.lastIndex, close), chain: stack.slice() });
      stack.push(el);
      re.lastIndex = close; last = close;
      continue;
    }
    if (VOID.has(tag) || /\/\s*$/.test(rawAttrs)) continue;
    stack.push(el);
  }
  addText(html.slice(last));
  if (stack.length) out.problems.push(`still open at the end: <${stack.map((e) => e.tag).join('>, <')}>`);
  return out;
}
const decode = (s) => String(s).replace(/&nbsp;/g, ' ').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&quot;/g, '"').replace(/&#39;/g, "'").replace(/&amp;/g, '&');
const stripTags = (html, sep = ' ') => html.replace(/<!--[\s\S]*?-->/g, sep).replace(/<(script|style)\b[\s\S]*?<\/\1>/gi, sep).replace(/<[^>]+>/g, sep);
const visibleText = (html) => decode(stripTags(html)).replace(/\s+/g, ' ').trim();
const inBody = (chain) => chain.some((e) => e.tag === 'body');
const inHead = (chain) => chain.some((e) => e.tag === 'head');
const words = (s) => visibleText(s).split(' ').filter(Boolean).length;
function webpSize(file) {
  const b = fs.readFileSync(path.join(ROOT, file));
  assert.ok(b.toString('ascii', 0, 4) === 'RIFF' && b.toString('ascii', 8, 12) === 'WEBP', `${file} is not a WebP`);
  const f = b.toString('ascii', 12, 16);
  if (f === 'VP8 ') return { w: b.readUInt16LE(26) & 0x3fff, h: b.readUInt16LE(28) & 0x3fff };
  if (f === 'VP8L') { const v = b.readUInt32LE(21); return { w: (v & 0x3fff) + 1, h: ((v >> 14) & 0x3fff) + 1 }; }
  if (f === 'VP8X') return { w: 1 + b.readUIntLE(24, 3), h: 1 + b.readUIntLE(27, 3) };
  throw new Error(`${file}: unknown WebP chunk ${f}`);
}
// does an internal path (with an optional query or hash) point at a page that exists, or at one that is planned?
function resolvable(href) {
  const p = href.replace(/[?#].*$/, '');
  if (PLANNED.has(p)) return true;
  if (p.endsWith('/')) return exists(p.slice(1) + 'index.html');
  return exists(p.slice(1));
}

// ══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
describe('llms.txt: what an AI assistant should know about the business', () => {
  const txt = exists('llms.txt') ? read('llms.txt') : '';
  const lines = txt.split('\n');
  const links = [...txt.matchAll(/\[([^\]]+)\]\(([^)\s]+)\)/g)].map((m) => ({ text: m[1], url: m[2] }));

  it('exists, is plain text of 120 lines or fewer, and follows the llms.txt convention: an H1, a blockquote summary, then H2 sections of links', () => {
    assert.ok(txt.length > 1500, 'llms.txt is missing or empty');
    assert.ok(lines.length <= 121, `${lines.length} lines`);
    assert.equal(lines[0], '# Barro Industries');
    assert.ok(/^> .{80,}/.test(lines.slice(1).find((l) => l.trim())), 'the blockquote summary is missing');
    const h2 = lines.filter((l) => /^## /.test(l)).map((l) => l.slice(3));
    for (const s of ['Services', 'Products', 'Projects', 'Areas served', 'How to get a quote', 'Contact']) assert.ok(h2.includes(s), `no "## ${s}" section`);
    assert.equal(lines.filter((l) => /^# /.test(l)).length, 1, 'more than one H1');
    assert.ok(!/<[a-z][^>]*>/i.test(txt), 'HTML in a plain-text file');
    assert.ok(txt.endsWith('\n') && !txt.endsWith('\n\n'));
    assert.ok(!/ +$/m.test(txt), 'trailing spaces');
  });

  it('links every services page, the catalogue, the six product pages and their hub, the projects, the areas page, the FAQ, the quote flow and Messenger', () => {
    const urls = new Set(links.map((l) => l.url));
    const need = ['/services/', '/services/commercial-kitchen-fit-out/', '/services/stainless-steel-fabrication/', '/services/exhaust-and-fresh-air-systems/', '/services/fresh-air-systems/', '/services/lpg-gas-line-installation/', '/services/kitchen-fire-suppression/', '/services/institutional-and-government-supply/',
      '/catalogue/', '/products/', '/products/stainless-steel-sinks/', '/products/stainless-steel-work-tables/', '/products/commercial-gas-stoves/', '/products/stainless-steel-cabinets/', '/products/stainless-steel-shelving/', '/products/stainless-steel-racks/',
      '/work/', '/work/ispsc-2026/', '/work/dmmmsu-2022-2023/', '/areas-we-serve/', '/faq/', '/catalogue/?quote=1', '/sales/clientinformationrequest/'];
    for (const n of need) assert.ok(urls.has(BASE + n), `llms.txt does not link ${n}`);
    assert.ok(urls.has(MSGR), 'no Messenger link');
  });

  it('only links to the business\'s own pages, its Messenger chat and its Facebook page, and every own page exists (or is one of the pages planned for 2026-10-22)', () => {
    assert.ok(links.length >= 25);
    for (const { url } of links) {
      if (url === MSGR || url === FB) continue;
      assert.ok(url.startsWith(BASE + '/'), `an outside link: ${url}`);
      assert.ok(resolvable(url.slice(BASE.length)), `llms.txt links ${url}, which does not exist and is not planned`);
    }
    for (const u of txt.match(/https?:\/\/[^\s)\]]+/g) || []) assert.ok(u.startsWith(BASE) || u === MSGR || u === FB, `an outside address: ${u}`);
    assert.equal(new Set(links.map((l) => l.url)).size, links.length, 'a page is linked twice');
  });

  it('states the facts the owner confirmed: the QC address, one phone, one email, the three registrations, the warranty, both grades, three finishes, 23 years, the family origin, the 13 places', () => {
    for (const f of [ADDRESS, PHONE, EMAIL, 'PhilGEPS-registered', 'SEC-registered', 'VAT-registered', '6-month service warranty', '12 months of preventive maintenance service (PMS) with KitchenShield™', 'food-grade SS304', 'laboratory-grade SS316', 'brushed, mirror or satin', '23 years', 'began as a family business in Baguio City and La Union', 'Barro Kitchens', 'Barro Industries OPC']) assert.ok(txt.includes(f), `llms.txt lacks "${f}"`);
    for (const p of PLACES) assert.ok(txt.includes(p), `llms.txt lacks ${p}`);
    assert.deepEqual([...new Set([...txt.matchAll(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[a-z]{2,}/g)].map((m) => m[0].toLowerCase()))], [EMAIL]);
    assert.deepEqual([...new Set([...txt.matchAll(/(?:\+?63[\s-]?|0)9\d{2}[\s-]?\d{3}[\s-]?\d{4}/g)].map((m) => m[0].replace(/\D/g, '').replace(/^63/, '0')))], ['09276836300']);
    assert.ok(!/\b(Barangay|Brgy|Makati|Pasig|Taguig|Cebu|Davao)\b/.test(txt), 'another address');
  });

  it('carries no amount, no banned name, no old contact detail, no system, no superlative, no project count, no client but DMMMSU and ISPSC, in British spelling', () => {
    assert.ok(!RE.money.test(txt), 'an amount');
    assert.ok(!RE.brands.test(txt.replace(/[\s\-_./]+/g, ' ')), 'a banned name');
    assert.ok(!RE.contact.test(txt), 'an old contact detail');
    assert.ok(!RE.system.test(txt), 'the system');
    assert.ok(!RE.superlative.test(txt), 'a superlative or an unverifiable claim');
    assert.ok(!RE.counts.test(txt), 'a project count');
    assert.ok(!RE.us.test(txt), 'a US spelling');
    assertInstitutions(txt, 'llms.txt');
    assert.ok(!/\b(Lorma|ITRMC|Bethany|Casa Carmelo|Cosmos|Chibab|Gerry|Jollibee|Starbucks|Plaza Premium)\b/i.test(txt), 'a client other than DMMMSU and ISPSC');
    assert.ok(/prices are not published/i.test(txt), 'it should say that prices are not published, so an assistant does not invent one');
  });

  it('does not list a guide while that guide is still a draft (noindex), and lists nothing that is not public', () => {
    for (const g of ['commissary-kitchen-requirements-philippines', 'ss304-vs-ss316-stainless-steel']) {
      const page = exists(`guides/${g}/index.html`) ? read(`guides/${g}/index.html`) : '';
      if (/<meta name="robots" content="noindex">/.test(page)) assert.ok(!txt.includes(`/guides/${g}/`), `${g} is a draft but llms.txt lists it`);
    }
    assert.ok(!txt.includes('/downloads/') || ['company-profile', 'catalogue', 'portfolio'].every((d) => !exists(`downloads/barro-industries-${d}.pdf`) || true));
    assert.ok(!/downloads\/src|\/private\/|\/q\/|\/t\/|\/v\/|\/projects\/|\/partners\/|\/docs\/|\/specs\//.test(txt), 'a private path');
  });
});

// ══════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════════
const GUIDES = [
  { path: '/guides/', kind: 'index' },
  { path: '/guides/commissary-kitchen-requirements-philippines/', kind: 'article', h1: 'Commissary Kitchen Requirements in the Philippines: Layout, Equipment and Ventilation', ogImage: 'og-fit-out.webp' },
  { path: '/guides/ss304-vs-ss316-stainless-steel/', kind: 'article', h1: 'SS304 vs SS316 Stainless Steel: Which Do You Need for Your Kitchen or Laboratory?', ogImage: 'og-fabrication.webp' },
];
const PAGES = GUIDES.map((g) => {
  const file = g.path.slice(1) + 'index.html';
  const html = exists(file) ? read(file) : '';
  const o = { ...g, file, url: BASE + g.path, html };
  if (!html) return o;
  const S = scan(html);
  o.S = S;
  o.head = html.slice(0, html.indexOf('</head>'));
  const headEls = S.elements.filter((e) => inHead(e.chain));
  o.meta = (key) => { const e = headEls.find((x) => x.tag === 'meta' && (x.attrs.name === key || x.attrs.property === key)); return e ? decode(e.attrs.content || '') : null; };
  o.metaCount = (key) => headEls.filter((x) => x.tag === 'meta' && (x.attrs.name === key || x.attrs.property === key)).length;
  o.links = (rel) => headEls.filter((x) => x.tag === 'link' && (x.attrs.rel || '').split(/\s+/).includes(rel)).map((x) => x.attrs);
  o.title = decode((html.match(/<title>([\s\S]*?)<\/title>/) || [, ''])[1]);
  o.ld = S.scripts.filter((s) => s.attrs.type === 'application/ld+json').map((s) => JSON.parse(s.body));
  o.graph = o.ld[0] && o.ld[0]['@graph'] ? o.ld[0]['@graph'] : [];
  o.node = (type) => o.graph.filter((n) => [].concat(n['@type']).includes(type));
  o.header = (html.match(/<header id="site-header">[\s\S]*?<\/header>/) || [''])[0];
  o.footer = (html.match(/<footer id="site-footer">[\s\S]*?<\/footer>/) || [''])[0];
  o.main = (html.match(/<main\b[\s\S]*?<\/main>/) || [''])[0];
  o.article = (html.match(/<article class="art">[\s\S]*?<\/article>/) || [''])[0];
  o.imgs = S.elements.filter((e) => e.tag === 'img');
  o.headings = [...html.matchAll(/<h([1-6])\b[^>]*>([\s\S]*?)<\/h\1>/g)].map((m) => ({ level: +m[1], text: visibleText(m[2]) }));
  o.draft = /<!-- DRAFT — awaiting owner approval/.test(html);
  o.body = S.texts.filter((t) => inBody(t.chain)).map((t) => decode(t.text)).join(' ').replace(/\s+/g, ' ').trim();
  return o;
});
const each = (fn) => { for (const p of PAGES) fn(p); };
const articles = PAGES.filter((p) => p.kind === 'article');
const byPath = (p) => PAGES.find((x) => x.path === p);
const publicStrings = (p) => {
  const out = [{ kind: 'title', value: p.title }];
  for (const t of p.S.texts) if (inBody(t.chain)) out.push({ kind: 'text', value: decode(t.text) });
  for (const a of p.S.attrs) if (['alt', 'title', 'aria-label', 'content', 'placeholder'].includes(a.name)) out.push({ kind: `<${a.tag} ${a.name}>`, value: decode(a.value) });
  for (const c of p.S.comments) out.push({ kind: 'comment', value: c.text });
  // the image-copyright markup (2026-10-22) is schema.org vocabulary, not copy: the key "license" and the type "Organization" are not claims or a US spelling
  for (const s of p.S.scripts) if (s.attrs.type === 'application/ld+json') out.push({ kind: 'json-ld', value: s.body.replace(/"license":\s*"https:\/\/barroindustries\.com\/#copyright"/g, '""').replace(/"@type":\s*"Organization"/g, '"@type": ""') });
  return out;
};
const firstHit = (p, re) => { const hit = publicStrings(p).find((s) => re.test(s.value)); return hit ? `${hit.kind}: "${(hit.value.match(re) || [])[0]}"` : null; };
const allStrings = (v, out = []) => { if (typeof v === 'string') out.push(v); else if (Array.isArray(v)) v.forEach((x) => allStrings(x, out)); else if (v && typeof v === 'object') Object.values(v).forEach((x) => allStrings(x, out)); return out; };
const allKeys = (v, out = new Set()) => { if (Array.isArray(v)) v.forEach((x) => allKeys(x, out)); else if (v && typeof v === 'object') for (const k of Object.keys(v)) { out.add(k); allKeys(v[k], out); } return out; };

describe('guides: the three pages exist, nothing else lives in the folder, and the stylesheet is scoped and clean', () => {
  it('has an index and the two articles, and no other file under /guides/', () => {
    for (const p of PAGES) assert.ok(p.html.length > 8000, `${p.file} is missing or empty`);
    const files = [];
    const walk = (d) => { for (const e of fs.readdirSync(path.join(ROOT, d), { withFileTypes: true })) (e.isDirectory() ? walk(`${d}/${e.name}`) : files.push(`${d}/${e.name}`)); };
    walk('guides');
    assert.deepEqual(files.sort(), PAGES.map((p) => p.file).sort());
  });

  it('has css/guides.css: scoped to #site, no 4-digit z-index (CHECK 1), no @import, no url(), no pricing words, nothing that touches the app', () => {
    const css = read('css/guides.css');
    assert.ok(css.length > 3000);
    assert.ok(/^\/\* css\/guides\.css/.test(css));
    const body = css.replace(/\/\*[\s\S]*?\*\//g, '');
    const selectors = body.replace(/\{[^{}]*\}/g, '{}').split(/[{}]/).map((x) => x.trim()).filter((x) => x && !/^@media/.test(x));
    for (const sel of selectors) for (const part of sel.split(',')) assert.ok(/^#site[\s.:>+~\[]|^#site$/.test(part.trim()), `a rule outside #site: ${part.trim()}`);
    assert.ok(!/z-index\s*:\s*\d{4}/.test(css));
    assert.ok(!/@import|url\(/.test(css));
    assert.ok(!/₱|\bPHP ?\d|\bpesos?\b/i.test(css) && !RE.brands.test(css));
  });

  it('keeps every page out of the service worker\'s PRECACHE and out of the app\'s scripts', () => {
    const sw = read('sw.js');
    assert.ok(!/'\/guides|'\/downloads|'\/css\/guides\.css'/.test(sw), 'sw.js precaches a guide, a download or the guides stylesheet');
    each((p) => assert.ok(!/<script[^>]*src="[^"]*(app|config|firebase|departments|modules|drive|notifications|quote-request|catalogue)[^"]*"/.test(p.html), `${p.path}: an app script`));
  });
});

describe('guides: <head> — title, description, canonical, robots, Open Graph, Twitter, CSP, fonts', () => {
  it('has one title of 45-65 characters ending "| Barro Industries", and every title is different', () => {
    each((p) => {
      assert.equal(p.S.elements.filter((e) => e.tag === 'title').length, 1, `${p.path}: title count`);
      assert.ok(p.title.length >= 45 && p.title.length <= 65, `${p.path}: title is ${p.title.length} characters`);
      assert.ok(p.title.endsWith(' | Barro Industries'));
      assert.ok(!/Barro Kitchens/i.test(p.title), 'the brand is not put in a title (owner ruling 2026-10-22: the pages keep their own titles)');
    });
    assert.equal(new Set(PAGES.map((p) => p.title)).size, PAGES.length);
  });

  it('has one description of 130-165 characters ending in a full stop, naming "Barro Kitchens" once, and every description is different', () => {
    each((p) => {
      assert.equal(p.metaCount('description'), 1);
      const d = p.meta('description');
      assert.ok(d.length >= 130 && d.length <= 165, `${p.path}: description is ${d.length} characters`);
      assert.ok(/[.]$/.test(d) && !/\s{2,}/.test(d));
      assert.equal((d.match(/Barro Kitchens/g) || []).length, 1, `${p.path}: the permanent name is in the description once`);
    });
    assert.equal(new Set(PAGES.map((p) => p.meta('description'))).size, PAGES.length);
  });

  it('has the canonical equal to the page\'s own URL', () => {
    each((p) => { const c = p.links('canonical'); assert.equal(c.length, 1); assert.equal(c[0].href, p.url); });
  });

  it('is a DRAFT: the comment "DRAFT — awaiting owner approval" and <meta name="robots" content="noindex"> go together (both until the owner approves, neither after)', () => {
    each((p) => {
      assert.equal(p.metaCount('robots'), 1, `${p.path}: robots meta count`);
      const robots = p.meta('robots');
      assert.ok(robots === 'noindex' || /^index,follow(,max-image-preview:large)?$/.test(robots), `${p.path}: robots is "${robots}"`);
      assert.equal(robots === 'noindex', p.draft, `${p.path}: the draft comment and the noindex disagree`);
      if (p.draft) assert.ok(/<!-- DRAFT — awaiting owner approval[^>]*-->/.test(p.head), 'the draft comment is in the head');
    });
  });

  it('keeps a draft out of sitemap.xml (and an approved page in it)', () => {
    const sm = read('sitemap.xml');
    each((p) => assert.equal(sm.includes(`<loc>${p.url}</loc>`), !p.draft, `${p.path}: sitemap.xml and the draft state disagree`));
  });

  it('is English, with the standard viewport, the site\'s icons and theme colour', () => {
    each((p) => {
      assert.match(p.html, /^<!DOCTYPE html>\s*<html lang="en" data-view="site">/);
      assert.equal(p.meta('viewport'), 'width=device-width, initial-scale=1.0, viewport-fit=cover');
      assert.equal(p.meta('theme-color'), '#FFFFFF');
      assert.ok(p.html.includes('<meta charset="UTF-8">'));
      assert.ok(p.html.includes('<link rel="icon" type="image/png" href="/favicon.png">') && p.html.includes('<link rel="apple-touch-icon" href="/icons/icon-192.png">'));
    });
  });

  it('has Open Graph and Twitter large-card tags that agree with the title and the description, and a real 1200 x 630 photo at an absolute URL from the existing pages\' images', () => {
    each((p) => {
      assert.equal(p.meta('og:type'), p.kind === 'article' ? 'article' : 'website');
      assert.equal(p.meta('og:site_name'), 'Barro Industries');
      assert.equal(p.meta('og:locale'), 'en_PH');
      assert.equal(p.meta('og:title'), p.title);
      assert.equal(p.meta('og:description'), p.meta('description'));
      assert.equal(p.meta('og:url'), p.url);
      assert.equal(p.meta('twitter:card'), 'summary_large_image');
      assert.equal(p.meta('twitter:title'), p.title);
      assert.equal(p.meta('twitter:description'), p.meta('description'));
      const img = p.meta('og:image');
      assert.match(img, /^https:\/\/barroindustries\.com\/site\/img\/pages\/og-[a-z-]+\.webp$/, 'a social image that already exists in the repo (no new file under site/img/)');
      assert.equal(p.meta('twitter:image'), img);
      assert.ok(exists(img.replace(BASE + '/', '')), `${img} does not exist`);
      const { w, h } = webpSize(img.replace(BASE + '/', ''));
      assert.deepEqual([String(w), String(h)], [p.meta('og:image:width'), p.meta('og:image:height')]);
      assert.deepEqual([w, h], [1200, 630]);
      assert.ok(p.meta('og:image:alt').length > 20 && p.meta('og:image:alt') === p.meta('twitter:image:alt'));
      if (p.ogImage) assert.ok(img.endsWith('/' + p.ogImage), `${p.path}: the social image should be ${p.ogImage}`);
      if (p.kind === 'article') { assert.equal(p.meta('article:published_time'), '2026-10-22'); assert.equal(p.meta('article:modified_time'), '2026-10-22'); }
    });
  });

  it('has the site\'s CSP (own files and the two font hosts only, no inline style or script, no unsafe-*), and loads fonts, site.css, pages.css, guides.css — nothing else', () => {
    each((p) => {
      assert.equal(p.html.match(/<meta http-equiv="Content-Security-Policy"/g).length, 1);
      const csp = p.html.match(/<meta http-equiv="Content-Security-Policy" content="([^"]*)">/)[1];
      assert.equal(csp, "default-src 'self'; script-src 'self'; style-src 'self' https://fonts.googleapis.com; font-src https://fonts.gstatic.com; img-src 'self' data:; frame-src 'none'; object-src 'none'; base-uri 'self'; form-action 'self'");
      assert.ok(!/unsafe-inline|unsafe-eval|\*|connect-src/.test(csp));
      const sheets = p.S.elements.filter((e) => e.tag === 'link' && e.attrs.rel === 'stylesheet').map((e) => e.attrs.href);
      assert.deepEqual(sheets, ['https://fonts.googleapis.com/css2?family=Fraunces:opsz,wght@9..144,500..600&family=Inter:wght@400;500;600&display=swap', '/css/site.css', '/css/pages.css', '/css/guides.css']);
      assert.ok(!p.S.elements.some((e) => e.tag === 'style') && !p.S.attrs.some((a) => a.name === 'style' || /^on[a-z]+$/.test(a.name)), `${p.path}: an inline style or handler`);
      assert.deepEqual(p.S.scripts.map((s) => s.attrs.src || s.attrs.type), ['application/ld+json', '/js/site.js']);
    });
  });
});

describe('guides: markup — one H1, a logical heading order, unique ids, sized and described images, working links', () => {
  it('is well-formed, with one <h1> that is the title the owner gave, one <main id="site-main">, one header, one footer and a skip link first', () => {
    each((p) => {
      assert.deepEqual(p.S.problems, [], p.path);
      assert.equal(p.headings.filter((h) => h.level === 1).length, 1);
      assert.equal(p.S.elements.filter((e) => e.tag === 'main').length, 1);
      assert.ok(/<main id="site-main" tabindex="-1">/.test(p.html));
      assert.equal(p.S.elements.filter((e) => e.tag === 'header' && e.attrs.id === 'site-header').length, 1);
      assert.equal(p.S.elements.filter((e) => e.tag === 'footer' && e.attrs.id === 'site-footer').length, 1);
      assert.ok(p.html.replace(/\s+/g, ' ').includes('<div id="site" class="pg"> <a class="skip-link" href="#site-main">Skip to the content</a>'));
      assert.ok(p.html.includes('</div><!-- /#site -->'));
      if (p.h1) assert.equal(p.headings.find((h) => h.level === 1).text, p.h1);
    });
    assert.equal(new Set(PAGES.map((p) => p.headings.find((h) => h.level === 1).text)).size, PAGES.length);
  });

  it('never skips a heading level, has no empty heading, and has 4+ headings', () => {
    each((p) => {
      let prev = 0;
      for (const h of p.headings) { assert.ok(h.text.length > 2); assert.ok(h.level <= prev + 1, `${p.path}: "${h.text}" jumps from h${prev} to h${h.level}`); prev = h.level; }
      assert.ok(p.headings.length >= 4);
    });
    for (const p of articles) assert.ok(p.headings.filter((h) => h.level === 2).length >= 6 && p.headings.some((h) => h.level === 3), `${p.path}: scannable H2 / H3 structure`);
  });

  it('has unique ids, every aria-labelledby, aria-controls and in-page link points at an id that exists', () => {
    each((p) => {
      const ids = p.S.elements.map((e) => e.attrs.id).filter(Boolean);
      assert.equal(new Set(ids).size, ids.length, `${p.path}: duplicate id`);
      for (const a of p.S.attrs.filter((x) => x.name === 'aria-labelledby' || x.name === 'aria-controls')) for (const id of a.value.split(/\s+/)) assert.ok(ids.includes(id), `${p.path}: ${a.name}="${id}" has no target`);
      for (const a of p.S.attrs.filter((x) => x.tag === 'a' && x.name === 'href' && x.value.startsWith('#'))) assert.ok(ids.includes(a.value.slice(1)), `${p.path}: ${a.value} has no target`);
    });
  });

  it('gives every image alt text, width and height equal to its file, an existing file, one high-priority hero (on the articles) and lazy everything else', () => {
    each((p) => {
      let high = 0;
      for (const { attrs: a } of p.imgs) {
        assert.ok(a.alt && a.alt.trim().length >= 10, `${p.path}: an image without alt text (${a.src})`);
        assert.match(a.src, /^\/site\/img\/(barro-kitchens-96\.webp|projects\/(ispsc|dmmmsu)\/\d\d(-thumb)?\.webp)$/, `${p.path}: unexpected image ${a.src}`);
        assert.ok(exists(a.src.slice(1)));
        const { w, h } = webpSize(a.src.slice(1));
        if (a.src === '/site/img/barro-kitchens-96.webp') assert.deepEqual([a.width, a.height], ['36', '36']);
        else { assert.equal(a.width, String(w)); assert.equal(a.height, String(h)); }
        if (a.srcset) for (const cand of a.srcset.split(',').map((s) => s.trim())) { const [u, d] = cand.split(/\s+/); assert.ok(exists(u.slice(1)), `srcset ${u}`); assert.equal(d, `${webpSize(u.slice(1)).w}w`); }
        if (a.fetchpriority === 'high') { high++; assert.ok(!a.loading); } else if (a.src !== '/site/img/barro-kitchens-96.webp') { assert.equal(a.loading, 'lazy'); assert.equal(a.decoding, 'async'); }
      }
      assert.equal(high, p.kind === 'article' ? 1 : 0, `${p.path}: fetchpriority="high" count`);
    });
  });

  it('uses, for every project photo, the alt text the homepage already uses for that same file (no new claim in an alt)', () => {
    const home = read('index.html');
    const homeAlts = {};
    for (const m of home.matchAll(/<img\b[^>]*?\bsrc="(site\/img\/projects\/(?:ispsc|dmmmsu)\/\d\d)(?:-thumb)?\.webp"[^>]*?\balt="([^"]*)"/g)) (homeAlts[m[1]] ||= new Set()).add(decode(m[2]));
    for (const m of home.matchAll(/<img\b[^>]*?\balt="([^"]*)"[^>]*?\bsrc="(site\/img\/projects\/(?:ispsc|dmmmsu)\/\d\d)(?:-thumb)?\.webp"/g)) (homeAlts[m[2]] ||= new Set()).add(decode(m[1]));
    each((p) => {
      for (const { attrs: a } of p.imgs) {
        const m = (a.src || '').match(/^\/(site\/img\/projects\/(?:ispsc|dmmmsu)\/\d\d)(?:-thumb)?\.webp$/);
        if (m) assert.ok(homeAlts[m[1]] && [...homeAlts[m[1]]].includes(decode(a.alt)), `${p.path}: the alt of ${a.src} is not one the homepage uses: "${a.alt}"`);
      }
    });
  });

  it('links only to pages that exist (or are planned), to the quote flow, the project brief, Messenger and Facebook, plus mailto and tel — and every page links home, to the catalogue and to the quote flow', () => {
    each((p) => {
      const hrefs = p.S.attrs.filter((a) => a.tag === 'a' && a.name === 'href').map((a) => a.value);
      for (const h of hrefs) {
        if (h.startsWith('#') || h.startsWith('mailto:') || h.startsWith('tel:')) continue;
        if (h === MSGR || h === FB) continue;
        assert.ok(h.startsWith('/'), `${p.path}: an outside link ${h}`);
        assert.ok(resolvable(h), `${p.path}: ${h} does not exist and is not planned`);
      }
      for (const u of ['/', '/catalogue/', '/catalogue/?quote=1', '/services/', ...(p.kind === 'article' ? ['/guides/'] : [])]) assert.ok(hrefs.includes(u), `${p.path} does not link ${u}`);
      assert.ok(hrefs.includes('mailto:' + EMAIL) && hrefs.includes('tel:+639276836300'));
    });
  });

  it('has the site\'s header and footer: the brand, the nav (the six sections, with or without the newer "Products" and "Guides" entries), "Get a quote" top right, the footer links ending with the discreet "Team portal", the three registrations and the QC address', () => {
    const MSG_ICON = '<svg class="msg-ic" viewBox="0 0 24 24" width="16" height="16" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="M7.9 20A9 9 0 1 0 4 16.1L2 22Z"/></svg>';
    const NEWER = new Set(['/products/', '/guides/']);
    each((p) => {
      assert.ok(p.header.includes('<a href="/" id="site-brand">') && p.header.includes('<span class="site-brand-sub"><span data-brand>Barro Kitchens</span>™</span>'));
      const nav = [...p.header.match(/<nav id="site-nav" aria-label="Main">([\s\S]*?)<\/nav>/)[1].matchAll(/<a href="([^"]+)">([^<]*)<\/a>/g)].map((m) => [m[1], m[2]]);
      assert.deepEqual(nav.filter((n) => !NEWER.has(n[0])), [['/services/', 'Services'], ['/work/', 'Our work'], ['/areas-we-serve/', 'Areas we serve'], ['/catalogue/', 'Catalogue'], ['/faq/', 'FAQ'], ['/#contact', 'Contact']]);
      assert.ok(p.header.includes('<a class="site-btn site-btn-primary site-btn-sm site-head-cta" href="/catalogue/?quote=1">Get a quote</a>'));
      assert.ok(p.header.indexOf('id="site-nav"') < p.header.indexOf('site-head-cta') && p.header.indexOf('site-head-cta') < p.header.indexOf('id="site-menu-btn"'));
      assert.ok(!/login/i.test(p.header));
      const row = p.footer.match(/<p class="foot-links">([\s\S]*?)<\/p>/)[1];
      const foot = [...row.replace(/<svg[\s\S]*?<\/svg>/g, '').matchAll(/<a\b[^>]*href="([^"]+)"[^>]*>([^<]+)<\/a>/g)].map((m) => [m[1], m[2]]);
      assert.deepEqual(foot.filter((n) => !NEWER.has(n[0])), [['/', 'Home'], ['/services/', 'Services'], ['/work/', 'Our work'], ['/areas-we-serve/', 'Areas we serve'], ['/faq/', 'FAQ'], ['/catalogue/', 'Catalogue'], [FB, 'Facebook'], [MSGR, 'Message us'], ['/catalogue/?quote=1', 'Get a quote'], ['/#login', 'Team portal']]);
      assert.ok(row.includes(`<a href="${MSGR}" rel="noopener" target="_blank" data-brand>${MSG_ICON}Message us</a>`) && row.includes(`<a href="${FB}" rel="noopener" target="_blank">Facebook</a>`));
      assert.ok(row.endsWith('<a class="foot-portal" href="/#login">Team portal</a>'));
      assert.ok(p.footer.includes(`<p>${ADDRESS}</p>`) && p.footer.includes('<p class="foot-name">Barro Industries OPC</p>'));
      assert.deepEqual([...p.footer.matchAll(/<li><svg[^>]*>[\s\S]*?<\/svg>([^<]+)<\/li>/g)].map((m) => m[1]), ['PhilGEPS-registered', 'SEC-registered', 'VAT-registered']);
      assert.deepEqual([...p.html.matchAll(/<a[^>]*href="\/#login"[^>]*>([^<]*)<\/a>/g)].map((m) => m[1]), ['Team portal']);
    });
  });

  it('has the closing call to action with a "Message us" button (Messenger, data-brand) beside the primary button, the phone and the email', () => {
    each((p) => {
      const cta = p.html.match(/<section class="pg-cta"[\s\S]*?<\/section>/)[0];
      assert.ok(cta.includes(`href="${MSGR}" rel="noopener" target="_blank" data-brand>`) && cta.includes('>Message us</a>'));
      assert.ok(cta.includes('<a href="tel:+639276836300">0927 683 6300</a>') && cta.includes(`<a href="mailto:${EMAIL}">${EMAIL}</a>`));
      assert.ok(/site-btn-primary"/.test(cta));
    });
    const c = byPath('/guides/commissary-kitchen-requirements-philippines/').html.match(/<section class="pg-cta"[\s\S]*?<\/section>/)[0];
    assert.ok(c.indexOf('/sales/clientinformationrequest/') < c.indexOf('href="/catalogue/?quote=1"') && c.indexOf('href="/catalogue/?quote=1"') < c.indexOf('m.me/barrokitchens'), 'commissary guide: the order of the closing calls is project brief, get a quote, Message us');
    assert.ok(/class="site-btn site-btn-primary" href="\/sales\/clientinformationrequest\/">Send a project brief/.test(c));
  });
});

describe('guides: JSON-LD — Article, BreadcrumbList, FAQPage (the visible Q&A word for word), CollectionPage — and nothing that is a price, an offer, a rating or a credential', () => {
  const BAD_KEYS = ['price', 'priceRange', 'priceCurrency', 'lowPrice', 'highPrice', 'offers', 'offer', 'makesOffer', 'hasOfferCatalog', 'availability', 'aggregateRating', 'ratingValue', 'ratingCount', 'reviewCount', 'bestRating', 'review', 'reviews', 'rating', 'openingHours', 'openingHoursSpecification', 'award', 'awards', 'hasCredential', 'vatID', 'taxID', 'slogan', 'paymentAccepted', 'currenciesAccepted'];

  it('has exactly one JSON-LD block that parses, is schema.org and is one @graph with unique @id values', () => {
    each((p) => {
      assert.equal(p.S.scripts.filter((s) => s.attrs.type === 'application/ld+json').length, 1);
      assert.equal(p.ld[0]['@context'], 'https://schema.org');
      assert.ok(Array.isArray(p.graph) && p.graph.length >= 2);
      const ids = p.graph.map((n) => n['@id']).filter(Boolean);
      assert.equal(new Set(ids).size, ids.length);
    });
  });

  it('carries no price, offer, rating, review, opening-hours or credential key anywhere, and no money in any string', () => {
    each((p) => {
      const keys = allKeys(p.ld);
      for (const k of BAD_KEYS) assert.ok(!keys.has(k), `${p.path}: a "${k}" key`);
      for (const s of allStrings(p.ld)) assert.ok(!RE.money.test(s) && !RE.priceWords.test(s), `${p.path}: money in JSON-LD: ${s.slice(0, 60)}`);
    });
  });

  it('gives each article an Article: the H1 as headline, datePublished 2026-10-22, an existing image, and the business as author AND publisher (an Organization named "Barro Industries", alternateName "Barro Kitchens", a logo)', () => {
    for (const p of articles) {
      const a = p.node('Article');
      assert.equal(a.length, 1, `${p.path}: Article count`);
      const n = a[0];
      assert.equal(n['@id'], p.url + '#article');
      assert.equal(n.headline, p.headings.find((h) => h.level === 1).text);
      assert.equal(n.description, p.meta('description'));
      assert.equal(n.datePublished, '2026-10-22');
      assert.equal(n.dateModified, '2026-10-22');
      assert.equal(n.inLanguage, 'en-PH');
      assert.deepEqual(n.image, [p.meta('og:image')]);
      for (const who of [n.author, n.publisher]) {
        assert.equal(who['@type'], 'Organization');
        assert.equal(who.name, 'Barro Industries');
        assert.ok(who.alternateName.includes('Barro Kitchens'));
        assert.equal(who.url, BASE + '/');
      }
      assert.equal(n.publisher.logo.url, BASE + '/icons/barro-kitchens.png');
      assert.ok(exists('icons/barro-kitchens.png'));
      assert.deepEqual(n.mainEntityOfPage, { '@id': p.url + '#webpage' });
      const wp = p.node('WebPage')[0];
      assert.equal(wp['@id'], p.url + '#webpage');
      assert.equal(wp.url, p.url);
      assert.equal(wp.name, n.headline);
      assert.deepEqual(wp.breadcrumb, { '@id': p.url + '#breadcrumb' });
      assert.deepEqual(wp.mainEntity, { '@id': p.url + '#article' });
      assert.equal(wp.primaryImageOfPage.url, p.meta('og:image'));
    }
  });

  it('has a BreadcrumbList that is the visible breadcrumb: the same names, the same links, the page itself last', () => {
    each((p) => {
      const bc = p.node('BreadcrumbList');
      assert.equal(bc.length, 1);
      assert.equal(bc[0]['@id'], p.url + '#breadcrumb');
      const visible = [...p.html.match(/<nav class="crumbs" aria-label="Breadcrumb"><ol>([\s\S]*?)<\/ol><\/nav>/)[1].matchAll(/<li>(?:<a href="([^"]+)">)?(?:<span aria-current="page">)?([^<]+)/g)].map((m) => [decode(m[2]), m[1] || null]);
      const items = bc[0].itemListElement;
      assert.equal(items.length, visible.length);
      assert.equal(items.length, p.path.split('/').filter(Boolean).length + 1);
      items.forEach((it, i) => { assert.equal(it.position, i + 1); assert.equal(it.name, visible[i][0]); assert.equal(it.item, BASE + (visible[i][1] || p.path)); });
      assert.deepEqual(items.slice(0, 2).map((i) => i.item), [BASE + '/', BASE + '/guides/'].slice(0, Math.min(2, items.length)));
    });
  });

  it('mirrors the visible Q&A exactly in FAQPage JSON-LD (same questions, same answers, same order), with 5 or 6 questions in sentence case ending "?"', () => {
    for (const p of articles) {
      const visible = [...p.html.matchAll(/<div class="faq-item">\s*<h3>([\s\S]*?)<\/h3>\s*<p>([\s\S]*?)<\/p>\s*<\/div>/g)].map((m) => [visibleText(m[1]), visibleText(m[2])]);
      const f = p.node('FAQPage');
      assert.equal(f.length, 1, `${p.path}: FAQPage count`);
      assert.equal(f[0]['@id'], p.url + '#faq');
      assert.deepEqual(f[0].isPartOf, { '@id': p.url + '#webpage' });
      const q = f[0].mainEntity;
      assert.equal(q.length, visible.length);
      assert.ok(visible.length >= 4 && visible.length <= 8, `${p.path}: ${visible.length} questions`);
      q.forEach((item, i) => {
        assert.equal(item['@type'], 'Question');
        assert.equal(item.acceptedAnswer['@type'], 'Answer');
        assert.equal(item.name, visible[i][0]);
        assert.equal(item.acceptedAnswer.text, visible[i][1]);
        assert.match(item.name, /^[A-Z][^?]*\?$/);
        assert.ok(!/\b[A-Z][a-z]+ [A-Z][a-z]+ [A-Z][a-z]+/.test(item.name.replace(/Barro Industries|SS304|SS316/g, 'x')), `a Title Case question: ${item.name}`);
        assert.ok(item.acceptedAnswer.text.length > 60);
      });
      assert.equal(new Set(q.map((x) => x.name)).size, q.length);
      assert.ok(p.html.includes('<section id="faq" aria-labelledby="faq-h">') && p.headings.some((h) => h.text === 'Frequently asked questions'));
    }
  });

  it('gives the index a CollectionPage whose ItemList is exactly the two articles, in page order, each linked from the page', () => {
    const ix = byPath('/guides/');
    const cp = ix.node('CollectionPage');
    assert.equal(cp.length, 1);
    assert.equal(cp[0]['@id'], ix.url + '#webpage');
    const list = cp[0].mainEntity;
    assert.equal(list['@type'], 'ItemList');
    assert.deepEqual(list.itemListElement.map((i) => i.url), articles.map((a) => a.url));
    assert.deepEqual(list.itemListElement.map((i) => i.name), articles.map((a) => a.headings.find((h) => h.level === 1).text));
    for (const i of list.itemListElement) assert.ok(ix.html.includes(`href="${i.url.replace(BASE, '')}"`));
    assert.equal(cp[0].publisher.name, 'Barro Industries');
  });
});

describe('guides: the owner\'s content rules (text, alt text, meta, JSON-LD, comments)', () => {
  it('shows no price, no peso sign, no thousands-separated number and none of the pricing words (CHECK 9 would refuse them in the body: "price", "pricing", "cost")', () => {
    each((p) => {
      assert.ok(!/basePrice|priceAdder|pricePer|rateW100|rateD100|rateH100|laborHours|ratePerDay|\bmarkup\b|₱|PHP ?[0-9]/i.test(p.html), `${p.path}: a price token`);
      assert.ok(!/\b[0-9]{1,3}(,[0-9]{3})+\b/.test(p.html.replace(/<link[^>]*fonts\.googleapis\.com[^>]*>/g, '')), `${p.path}: a thousands-separated number`);
      const body = p.html.slice(p.html.indexOf('</head>'));
      assert.ok(!/pric(e|ing)|[^a-z]costs?[^a-z]/i.test(body), `${p.path}: CHECK 9's body scan would fail`);
      assert.equal(firstHit(p, RE.money), null, p.path);
      assert.equal(firstHit(p, RE.priceWords), null, p.path);
    });
  });

  it('never names the partner company, Vesta or Barro Steel (in any spelling, slug or comment), and carries no old contact detail', () => {
    each((p) => {
      assert.ok(!RE.brands.test(p.html.replace(/[\s\-_./]+/g, ' ')), `${p.path}: a banned name`);
      assert.ok(!RE.contact.test(p.html), `${p.path}: an old contact detail`);
      const digits = [...p.html.matchAll(/(?:\+?63[\s-]?|0)9\d{2}[\s-]?\d{3}[\s-]?\d{4}/g)].map((m) => m[0].replace(/\D/g, '').replace(/^63/, '0'));
      assert.ok(digits.length >= 1 && digits.every((d) => d === '09276836300'), `${p.path}: phone numbers ${digits}`);
      assert.deepEqual([...new Set([...p.html.matchAll(/[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[a-z]{2,}/g)].map((m) => m[0].toLowerCase()))], [EMAIL]);
      assert.equal((p.body.match(/Capricorn/g) || []).length, 1, `${p.path}: the street address appears once (the footer)`);
      assert.ok(!/\b(Barangay|Brgy|Poblacion|Makati|Pasig|Taguig|Cebu|Davao)\b/.test(p.body), `${p.path}: another address`);
      assert.ok(!/La\s*Union/i.test(p.footer + p.header), `${p.path}: La Union in the header or footer`);
    });
  });

  it('states no project count, names no client but DMMMSU and ISPSC, shows no agency logo, and credits no grade, finish or compliance to a project', () => {
    each((p) => {
      assert.equal(firstHit(p, RE.counts), null, p.path);
      for (const t of p.S.texts.filter((x) => inBody(x.chain))) assertInstitutions(decode(t.text), p.path);
      assert.equal(firstHit(p, /\b(Lorma|ITRMC|Bethany|Casa Carmelo|Cosmos|Chibab|Gerry|Jollibee|Starbucks|Marriott|Hilton|Plaza Premium)\b/i), null, p.path);
      assert.ok(!/<(object|embed|iframe|picture|canvas|video|audio)\b/i.test(p.html));
    });
    const steel = byPath('/guides/ss304-vs-ss316-stainless-steel/');
    assert.ok(!/\b(ISPSC|DMMMSU|Ilocos|La Union)\b/.test(steel.body), 'the grade guide names no project, so it cannot imply a grade for one');
  });

  it('claims no "best / leading / world-class / award / certified / accredited / licensed / guaranteed", no #1, no superlative', () => {
    each((p) => assert.equal(firstHit(p, RE.superlative), null, p.path));
  });

  it('never mentions the system, the app, a login or the staff — the one way in is the footer "Team portal" link', () => {
    each((p) => {
      assert.equal(firstHit(p, RE.system), null, p.path);
      assert.ok(!/\b(staff|employees?|admin|dashboard)\b/i.test(p.body), `${p.path}: staff / admin vocabulary`);
      assert.ok(!/\bportal\b/i.test(p.body.replace('Team portal', '')));
    });
  });

  it('is copyright-marked (owner approved 2026-10-22): author and copyright meta, copyrightHolder and copyrightYear in the JSON-LD, and a visible notice at the foot of the article', () => {
    each((p) => {
      assert.equal(p.meta('author'), 'Barro Industries OPC');
      assert.equal(p.meta('copyright'), '© 2026 Barro Industries OPC. All rights reserved.');
      const notice = [...p.html.matchAll(/<p class="art-copy[^"]*">([\s\S]*?)<\/p>/g)].map((m) => visibleText(m[1]));
      assert.deepEqual(notice, ['© 2026 Barro Industries OPC. All rights reserved. All text, photographs and designs on this page are our own work and may not be copied or reused without written permission.'], `${p.path}: the visible copyright notice`);
      assert.ok(/© <span id="site-year">2026<\/span> Barro Industries OPC/.test(p.footer) && /may not be copied or reused without written permission/.test(p.footer), `${p.path}: the footer's own copyright line`);
      const holder = (n) => { assert.equal(n.copyrightHolder['@type'], 'Organization'); assert.equal(n.copyrightHolder.name, 'Barro Industries'); assert.deepEqual(n.copyrightHolder.alternateName, ['Barro Kitchens', 'Barro Kitchens by Barro Industries']); assert.equal(n.copyrightYear, 2026); };
      if (p.kind === 'article') { const n = p.node('Article')[0]; holder(n); assert.equal(n.copyrightNotice, '© 2026 Barro Industries OPC. All rights reserved.'); }
      else holder(p.node('CollectionPage')[0]);
    });
    for (const p of articles) assert.ok(p.article.includes('<p class="art-copy">'), `${p.path}: the notice is inside the article column`);
  });

  it('is written in British English, with no doubled space and no hyphen used as a dash', () => {
    each((p) => {
      for (const s of [...publicStrings(p).filter((x) => x.kind !== 'json-ld').map((x) => x.value), ...ldValues(p.ld)]) assert.ok(!RE.us.test(s), `${p.path}: a US spelling: ${(s.match(RE.us) || [])[0]}`);
      const segments = stripTags(p.html.slice(p.html.indexOf('<body')), '\u0001').split('\u0001').map((s) => s.trim()).filter(Boolean);
      for (const s of segments) assert.ok(!/\S {2,}\S/.test(s), `${p.path}: doubled space in "${s.slice(0, 50)}"`);
      assert.ok(!/ -- |\s-\s(?=[A-Za-z])/.test(p.body));
      assert.ok(!/KitchenShield(?!™)/.test(p.body));
    });
  });

  it('keeps "Barro Kitchens" in the permanent places only: the header span (once, bare, the swap point of a rename), the footer\'s copyright notice (a bare data-brand-legacy span, what a rename keeps), the meta descriptions and the JSON-LD alternateName — never in a title, an alt or an aria-label', () => {
    each((p) => {
      const count = (s) => (String(s).match(/Barro\s+Kitchens/gi) || []).length;
      const visible = p.S.texts.filter((t) => count(t.text));
      assert.equal(visible.length, 2, `${p.path}: visible mentions`);
      assert.deepEqual(visible[0].chain[visible[0].chain.length - 1].attrs, { 'data-brand': '' });
      assert.equal(visible[0].text, 'Barro Kitchens');
      assert.deepEqual(visible[1].chain[visible[1].chain.length - 1].attrs, { 'data-brand-legacy': '' });   // owner 2026-10-22: "© 2026 Barro Industries OPC (Barro Kitchens). All photos, designs and content …"
      assert.equal(visible[1].text, 'Barro Kitchens');
      for (const k of ['og:title', 'twitter:title', 'og:site_name', 'og:image:alt', 'twitter:image:alt']) assert.ok(!count(p.meta(k)), `${p.path}: ${k}`);
      for (const k of ['description', 'og:description', 'twitter:description']) assert.equal(count(p.meta(k)), 1);
      assert.deepEqual(p.S.attrs.filter((a) => count(a.value)).map((a) => `${a.tag}[${a.name}]`), ['meta[content]', 'meta[content]', 'meta[content]']);
      assert.ok(p.S.comments.every((c) => !count(c.text)));
      for (const n of p.graph) if (n.author) assert.deepEqual(n.author.alternateName, ['Barro Kitchens', 'Barro Kitchens by Barro Industries']);
    });
  });
});

describe('guides: the two articles — length, structure, and what each one says (and does not)', () => {
  const commissary = byPath('/guides/commissary-kitchen-requirements-philippines/');
  const steel = byPath('/guides/ss304-vs-ss316-stainless-steel/');

  it('is 900-1600 words long, whether counted as the article or as the whole <main>', () => {
    for (const p of articles) {
      const n = words(p.article), m = words(p.main.replace(/<script[\s\S]*?<\/script>/g, ''));
      assert.ok(n >= 900 && n <= 1600, `${p.path}: the article is ${n} words`);
      assert.ok(m >= 900 && m <= 1600, `${p.path}: <main> is ${m} words`);
    }
  });

  it('opens with a short "In short" summary and a contents list whose every entry links to a section of the article', () => {
    for (const p of articles) {
      assert.ok(p.article.includes('<p class="art-keys-title">In short</p>'));
      const toc = [...p.html.match(/<nav class="art-toc"[\s\S]*?<\/nav>/)[0].matchAll(/<a href="#([^"]+)">([^<]+)<\/a>/g)].map((m) => m[1]);
      assert.ok(toc.length >= 6);
      for (const id of toc) assert.ok(new RegExp(`<section id="${id}"`).test(p.article), `${p.path}: the contents entry #${id} has no section`);
      assert.ok(/<time datetime="2026-10-22">22 October 2026<\/time>/.test(p.html) && p.html.includes('By Barro Industries'));
    }
  });

  it('commissary guide: the six zones, equipment by zone, stainless surfaces, exhaust and fresh air, LPG lines and fire suppression, sanitation-friendly materials and a planning checklist', () => {
    const t = commissary.article;
    for (const z of ['Receiving', 'Storage', 'Preparation', 'Cooking', 'Washing', 'Packing and dispatch']) assert.ok(new RegExp(`<th scope="row">${z}</th>`).test(t), `the zones table lacks ${z}`);
    for (const f of ['Typical equipment', 'Stainless-steel work surfaces', 'Floors, walls and drains', 'Exhaust and fresh air', 'LPG gas lines', 'Fire suppression', 'A planning checklist', 'fresh-air supply replaces', 'welded black-iron', 'secured cage', 'emergency auto-shutoff valve', 'wet chemical', 'welded and ground smooth']) assert.ok(t.includes(f), `the commissary guide lacks "${f}"`);
    const checks = [...t.match(/<ul class="art-check">([\s\S]*?)<\/ul>/)[1].matchAll(/<li>/g)].length;
    assert.ok(checks >= 10 && checks <= 20, `${checks} checklist items`);
  });

  it('commissary guide: sends the reader to the local government unit, the sanitary or health office and the fire safety inspector — and states no specific law, permit name, code clause or number', () => {
    const t = commissary.article;
    assert.ok(/local government unit/.test(t) && /sanitary or health office/.test(t) && /fire safety inspector/.test(t));
    assert.ok(/not legal advice/.test(t));
    assert.ok(/Which permits does a commissary kitchen need in the Philippines\?/.test(t) && /so we do not list permits here/.test(t));
    assert.equal(firstHit(commissary, RE.legal), null);
    assert.ok(!/\b(regulations?|compliance|compliant|complies|standards|(?:industry|international|national|safety|quality|building|fire|sanitation) (?:standard|code)s?)\b/i.test(commissary.body), 'a regulation, compliance or standards claim');
    assert.ok(!/\b\d+(\.\d+)?\s*(%|per cent|percent)\b/.test(commissary.body), 'a statistic in the commissary guide');
  });

  it('commissary guide: links the fit-out, exhaust, fresh-air, LPG and fire-suppression services, the grade guide, the catalogue and the six product pages', () => {
    const hrefs = new Set(commissary.S.attrs.filter((a) => a.tag === 'a' && a.name === 'href').map((a) => a.value));
    for (const u of ['/services/commercial-kitchen-fit-out/', '/services/exhaust-and-fresh-air-systems/', '/services/fresh-air-systems/', '/services/lpg-gas-line-installation/', '/services/kitchen-fire-suppression/', '/guides/ss304-vs-ss316-stainless-steel/', '/catalogue/', '/sales/clientinformationrequest/', '/products/stainless-steel-racks/', '/products/stainless-steel-shelving/', '/products/stainless-steel-cabinets/', '/products/stainless-steel-work-tables/', '/products/stainless-steel-sinks/', '/products/commercial-gas-stoves/']) assert.ok(hrefs.has(u), `the commissary guide does not link ${u}`);
  });

  it('grade guide: molybdenum, chlorides, 304 as the food-grade standard, 316 for laboratories, coastal and chemical exposure, both grades "look the same", three finishes, care tips — and "generally" more expensive, with no amount', () => {
    const t = steel.article;
    for (const f of ['molybdenum', 'chlorides', 'austenitic', '18/8', 'SS304 is the standard food-grade stainless steel for kitchens', 'laboratories, coastal sites and chemical exposure', 'You cannot tell the grades apart by eye', 'Brushed:', 'Mirror:', 'Satin:', 'Caring for stainless steel', 'soft cloth', 'generally the more expensive', 'Laboratory-grade SS316 is available from us on request', 'food-grade SS304 as standard']) assert.ok(t.includes(f), `the grade guide lacks "${f}"`);
    assert.ok(/<table class="pg-table">[\s\S]*SS304[\s\S]*SS316/.test(t), 'a comparison table');
    assert.ok(!/\b(more|less) than \d+ times\b|\btwice\b|\b\d+x\b/i.test(steel.body), 'a multiple');
    const hrefs = new Set(steel.S.attrs.filter((a) => a.tag === 'a' && a.name === 'href').map((a) => a.value));
    for (const u of ['/services/stainless-steel-fabrication/', '/catalogue/', '/guides/commissary-kitchen-requirements-philippines/', '/products/stainless-steel-work-tables/', '/products/stainless-steel-sinks/', '/products/stainless-steel-cabinets/', '/products/stainless-steel-shelving/', '/products/stainless-steel-racks/', '/sales/clientinformationrequest/']) assert.ok(hrefs.has(u), `the grade guide does not link ${u}`);
  });

  it('grade guide: says SS316 is available on request, and nothing that puts an SS316 option in the online quote flow', () => {
    assert.ok(/If you need SS316, say so when you message us or send a/.test(steel.article));
    assert.ok(!/online quote[^.]*SS316|SS316[^.]*online quote/i.test(steel.body));
  });
});

