describe('downloads: the build — script, stylesheet, embedded font, HTML sources', () => {
  it('has scripts/build-downloads.js with the way to regenerate all three documents written at its head, and the three document modules', () => {
    const s = read('scripts/build-downloads.js');
    assert.ok(/^#!\/usr\/bin\/env node\n'use strict';\n\/\*/.test(s));
    assert.ok(/RUN:\s+node scripts\/build-downloads\.js/.test(s) && /headless Chrome/.test(s) && /--print-to-pdf/.test(s));
    for (const d of ['profile', 'catalogue', 'portfolio', 'lib', 'pdf-text']) assert.ok(exists(`scripts/downloads/${d}.js`), `scripts/downloads/${d}.js`);
    for (const out of ['barro-industries-company-profile.pdf', 'barro-industries-catalogue.pdf', 'barro-industries-portfolio.pdf']) assert.ok(s.includes(out));
  });

  it('has the shared print stylesheet and Fraunces embedded from a local file with its OFL licence beside it (nothing is fetched at build time)', () => {
    const css = read('downloads/src/print.css');
    assert.ok(/@page\{size:210mm 297mm;margin:0\}/.test(css));
    assert.ok(/fraunces-latin-600-normal\.woff2/.test(css) && !/https?:\/\//.test(css.replace(/\/\*[\s\S]*?\*\//g, '')), 'the stylesheet must not fetch anything');
    assert.ok(exists('downloads/src/fonts/fraunces-latin-600-normal.woff2') && fs.statSync(path.join(ROOT, 'downloads/src/fonts/fraunces-latin-600-normal.woff2')).size > 10000);
    assert.ok(/SIL OPEN FONT LICENSE Version 1\.1/.test(read('downloads/src/fonts/Fraunces-OFL.txt')));
    assert.ok(!/₱|\bPHP ?\d|\bpesos?\b/i.test(css) && !RE.brands.test(css));
  });

  it('has the three HTML sources, each noindex, generated (not hand-edited), with one .page per PDF page, no client name, and no banned content', () => {
    for (const [html, pdf] of [['company-profile', 'barro-industries-company-profile'], ['catalogue', 'barro-industries-catalogue'], ['portfolio', 'barro-industries-portfolio']]) {
      const h = read(`downloads/src/${html}.html`);
      assert.ok(/<meta name="robots" content="noindex">/.test(h) && /GENERATED by scripts\/build-downloads\.js/.test(h));
      const pages = (h.match(/<section class="page\b/g) || []).length;
      assert.equal(pages, pdfInfo(path.join(ROOT, `downloads/${pdf}.pdf`)).pageCount, `${html}: the HTML has ${pages} pages, the PDF another number — rebuild`);
      const vis = visibleText(h);
      assert.ok(!RE.money.test(vis) && !RE.priceWords.test(vis) && !RE.brands.test(h.replace(/[\s\-_./]+/g, ' ')) && !RE.contact.test(h), `${html}: banned content in the source`);
      assert.ok(!/gerry/i.test(h), `${html}: the anonymised restaurant is named`);
    }
    for (const f of fs.readdirSync(path.join(ROOT, 'downloads/src/img'))) assert.ok(!/gerry|brilliant|vesta|barro-?steel/i.test(f), `a banned name in the file name ${f}`);
  });

  it('keeps the images light: nothing in downloads/src/img is over 500 KB, every image is a JPEG, and the folder stays under 8 MB', () => {
    let total = 0;
    for (const f of fs.readdirSync(path.join(ROOT, 'downloads/src/img'))) {
      const st = fs.statSync(path.join(ROOT, 'downloads/src/img', f));
      assert.ok(/\.jpg$/.test(f), `${f} is not a JPEG`);
      assert.ok(st.size < 500 * 1024, `${f} is ${(st.size / 1024).toFixed(0)} KB`);
      total += st.size;
    }
    assert.ok(total < 8 * 1024 * 1024, `${(total / 1048576).toFixed(1)} MB of images`);
  });
});

describe('downloads: the pictures that only the PDFs use are copyright-marked (owner approved 2026-10-22), like the website\'s photographs', () => {
  const MARKED = ['ispsc-01.jpg', 'own-fire-diagram.jpg', 'own-gas-tank-farm.jpg', 'own-gas-valve-a.jpg', 'own-gas-valve-b.jpg', 'own-hoods.jpg', 'own-inline-fan.jpg', 'own-president.jpg', 'restaurant-1.jpg', 'restaurant-2.jpg', 'restaurant-3.jpg', 'restaurant-4.jpg'];

  it('has scripts/watermark-downloads.py, which reuses the look of scripts/watermark-images.py (stamp() and XMP), keeps un-marked masters under the gitignored private/ folder, and never stacks a mark', () => {
    const py = read('scripts/watermark-downloads.py');
    assert.ok(/^#!\/usr\/bin\/env python3/.test(py) && /watermark-images\.py/.test(py) && /wm\.stamp\(/.test(py) && /wm\.XMP/.test(py));
    assert.ok(/private\/img-masters\/downloads/.test(py) && /rebuilds the public file FROM its master/.test(py));
    assert.ok(/^\/private\/$/m.test(read('.gitignore')), 'private/ is not ignored: the masters would be published');
    assert.ok(!exists('downloads/src/img-masters') && !fs.readdirSync(path.join(ROOT, 'downloads')).some((f) => /master/i.test(f)), 'a master inside downloads/');
  });

  it('carries the copyright XMP packet (rights, creator, web statement) inside each of those JPEGs, and the website photographs they sit beside are converted from the marked site/img files', () => {
    for (const f of MARKED) {
      const b = fs.readFileSync(path.join(ROOT, 'downloads/src/img', f));
      assert.ok(b[0] === 0xff && b[1] === 0xd8, `${f} is not a JPEG`);
      const t = b.toString('latin1');
      for (const n of ['xmpRights:Marked="True"', 'Barro Industries OPC', 'barroindustries.com']) assert.ok(t.includes(n), `${f} lacks ${n}`);
    }
    const lib = read('scripts/downloads/lib.js');
    assert.ok(/site\/img\/projects\/ispsc\/\$\{n\}\.webp/.test(lib) && /site\/img\/products\//.test(lib), 'the site photographs come from site/img');
    assert.ok(!/Desktop|Downloads/.test(lib), 'a photograph is taken from outside the repository');
  });

  it('stamps the big ones visibly: the corner of each stamped picture differs from its master, and the website photograph is not a master (it carries the site\'s own mark)', () => {
    const masters = path.join(ROOT, 'private/img-masters/downloads');
    if (!fs.existsSync(masters)) return;   // a clone without the private masters cannot compare: the XMP test above still holds
    for (const f of ['restaurant-1.jpg', 'own-hoods.jpg', 'ispsc-01.jpg']) {
      if (!fs.existsSync(path.join(masters, f))) continue;
      assert.notDeepEqual(fs.readFileSync(path.join(ROOT, 'downloads/src/img', f)), fs.readFileSync(path.join(masters, f)), `${f} is not stamped`);
    }
  });
});

